def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if budget <= 0:
        return 0.0

    if len(alive_opps) == 0:
        return float(min(budget, 20.0))

    prev_bids = []
    dangerous_bids = []
    weak_count = 0
    rich_danger = 0

    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 110:
                dangerous_bids.append(float(bid))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            weak_count += 1
        if opp.get('budget', 0) >= 120 and opp.get('hp', 0) > 3:
            rich_danger += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 7:
        urgency += 0.2

    if no_water >= 2:
        urgency += 1.0
    elif no_water == 1:
        urgency += 0.45

    if day >= 8:
        urgency += 0.15

    if weak_count >= 2:
        urgency -= 0.1

    base = 18.0 + 32.0 * scarcity + 26.0 * urgency

    if scarcity > 0.7 or urgency > 0.9:
        target = max(base, highest_prev + 2.0)
    elif scarcity > 0.4:
        target = max(base, avg_prev * 0.82 + 4.0)
    else:
        target = base

    if rich_danger >= 2 and hp > 4 and no_water == 0 and scarcity < 0.5:
        target *= 0.72

    if hp <= 2 or no_water >= 2:
        target = max(target, 95.0)
    elif hp <= 4 or no_water == 1:
        target = max(target, 62.0)

    max_safe = budget
    if hp > 5 and no_water == 0:
        reserve = DAILY_SALARY * 2.2
        max_safe = max(0.0, budget - reserve)
        if max_safe < 20.0:
            max_safe = min(budget, 20.0)
    elif hp > 3:
        reserve = DAILY_SALARY * 1.2
        max_safe = max(0.0, budget - reserve)
        if max_safe < 35.0:
            max_safe = min(budget, 35.0)

    bid = min(target, max_safe if max_safe > 0 else budget)

    if scarcity < 0.25 and hp >= 8 and no_water == 0:
        bid = min(bid, 28.0)

    if highest_prev >= 145 and hp > 4 and no_water == 0 and scarcity < 0.8:
        bid = min(bid, 55.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 1)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from traces for immediate reaction
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass
        elif isinstance(prev, list) and prev:
            # If trace is list-like, take last element
            last = prev[-1]
            if isinstance(last, dict):
                b = last.get('bid', None)
                if b is not None:
                    try:
                        yesterday_bids.append(float(b))
                    except Exception:
                        pass

    # Determine competitive pressure from yesterday
    top_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are realistically needed/available this day
    # supply is total pool; each unit costs WATER_REQ water.
    # We only use it to scale aggressiveness, not to compute exact allocation.
    try:
        units_available = int(supply / float(WATER_REQ))
    except Exception:
        units_available = 1
    if units_available < 1:
        units_available = 1

    # Baseline bid aggressiveness
    # If my hp is low or I have been without water, I must bid more.
    hp_pressure = 0.0
    if hp <= 1:
        hp_pressure = 1.0
    elif hp <= 3:
        hp_pressure = 0.7
    elif hp <= 5:
        hp_pressure = 0.4

    if no_water_days >= 2:
        hp_pressure = max(hp_pressure, 0.8)

    # Supply scaling: higher supply -> can bid slightly less; lower supply -> bid more.
    # Normalize supply between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY != MIN_SUPPLY:
        supply_norm = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Convert yesterday top pressure into a target bid band.
    # Yesterday winners had max bids around ~152; we target below top to conserve budget.
    # If top_bid is very high, we must match closer.
    if top_bid >= DAILY_SALARY * 1.45:
        base_target = DAILY_SALARY * 0.95
    elif top_bid >= DAILY_SALARY * 1.2:
        base_target = DAILY_SALARY * 0.75
    elif top_bid >= DAILY_SALARY * 0.8:
        base_target = DAILY_SALARY * 0.62
    else:
        base_target = DAILY_SALARY * 0.55

    # Adjust target by supply and my health pressure
    # Lower supply -> higher bid; low hp -> higher bid.
    bid_scale = (1.0 - 0.25 * supply_norm) + 0.6 * hp_pressure
    target_bid = base_target * bid_scale

    # Ensure we react to yesterday's top bid: if top_bid is close to our baseline, bump slightly.
    # Add a small epsilon to beat likely tie margins.
    if top_bid > 0:
        # If top_bid is not too far above target, move toward it.
        if top_bid <= target_bid * 1.15:
            target_bid = (0.7 * target_bid) + (0.3 * top_bid) + 1.5
        else:
            # Otherwise, still try to be competitive but not reckless.
            target_bid = min(target_bid, top_bid * 0.85)

    # Cap by budget and keep within reasonable bounds
    # Also avoid bidding more than we can afford.
    max_affordable = max(0.0, float(budget))

    # If budget is very low, bid just enough to avoid starvation.
    if max_affordable <= 1.0:
        return 0.0

    # Final bid rule
    # Keep a floor so we don't lose when others overbid; but don't exceed 95% of budget.
    min_floor = DAILY_SALARY * 0.35
    bid = max(min_floor, target_bid)
    bid = min(bid, max_affordable * 0.95)

    # If hp is critical, push closer to budget.
    if hp <= 2:
        bid = min(max_affordable * 0.98, max(bid, DAILY_SALARY * 0.85))

    # If supply is very low, push a bit more.
    if float(supply) <= float(MIN_SUPPLY) + 0.5:
        bid = min(max_affordable * 0.98, bid * 1.08)

    # Return non-negative float
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect previous bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    # Base bid: moderate
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents were very aggressive
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp > 3:
                # Conserve, bid low to recover budget
                bid = min(budget, DAILY_SALARY * 0.3)
            else:
                # Need water, bid competitively
                bid = min(budget, DAILY_SALARY * 0.95)
        else:
            # Opponents moderate, we can be slightly above or safe
            safe_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
            bid = min(budget, safe_bid)
    else:
        # No trace, fallback
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.55)

    # Adjust for supply tightness
    if supply < (WATER_REQ * len(alive_opponents) + 1):
        # Water scarce, increase bid if necessary
        bid = max(bid, min(budget, DAILY_SALARY * 0.8))

    # Ensure we can't bid more than budget
    return min(budget, bid)
